/// A node in the parse tree. `data` is the rule name (or alias) that built it.
///
/// `Drop` and `Clone` are manual worklist implementations (#151, same as the
/// main crate's `Tree`): the derived glue recurses to tree depth, and a parse
/// result is as deep as the input is nested, so the derived glue overflows
/// small native stacks.
#[derive(Debug)]
pub struct Tree {
    pub data: &'static str,
    pub children: Vec<Child>,
    pub meta: Meta,
}

impl Drop for Tree {
    fn drop(&mut self) {
        let is_tree = |c: &Child| matches!(c, Child::Tree(_));
        // Fast path: leaf-only children drop in place — no recursion possible.
        if !self.children.iter().any(is_tree) {
            return;
        }
        // Worklist of whole `children` vectors (3-word moves, never per-element
        // copies). Invariant: a vector is pushed only if it contains a subtree
        // with sub-subtrees; every `Tree` value therefore reaches its own
        // (recursive) drop with empty or leaf-only children, where the fast
        // path returns immediately — so native depth stays constant.
        let mut stack: Vec<Vec<Child>> = vec![std::mem::take(&mut self.children)];
        while let Some(mut vec) = stack.pop() {
            for child in vec.iter_mut() {
                if let Child::Tree(t) = child {
                    if t.children.iter().any(is_tree) {
                        stack.push(std::mem::take(&mut t.children));
                    }
                }
            }
            // `vec` drops here; every tree in it is now empty or leaf-only.
        }
    }
}

impl Clone for Tree {
    fn clone(&self) -> Self {
        // Explicit-frame deep copy: one heap frame per open node instead of one
        // native frame per tree level.
        struct Frame<'a> {
            src: std::slice::Iter<'a, Child>,
            data: &'static str,
            meta: Meta,
            out: Vec<Child>,
        }
        fn frame(t: &Tree) -> Frame<'_> {
            Frame {
                src: t.children.iter(),
                data: t.data,
                meta: t.meta.clone(),
                out: Vec::with_capacity(t.children.len()),
            }
        }
        let mut stack = vec![frame(self)];
        loop {
            let top = stack
                .last_mut()
                .expect("clone stack never empties mid-walk");
            match top.src.next() {
                Some(Child::Tree(t)) => stack.push(frame(t)),
                Some(Child::Token(tok)) => top.out.push(Child::Token(tok.clone())),
                Some(Child::None) => top.out.push(Child::None),
                None => {
                    let done = stack.pop().expect("just peeked");
                    let tree = Tree {
                        data: done.data,
                        children: done.out,
                        meta: done.meta,
                    };
                    match stack.last_mut() {
                        Some(parent) => parent.out.push(Child::Tree(tree)),
                        None => return tree,
                    }
                }
            }
        }
    }
}

/// The result of a parse — usually a `Tree`, but a `?start` rule that collapses
/// via expand1 to a single token yields that bare `Token`, and a `?start` whose
/// sole alternative is an absent `[...]` placeholder collapses to a bare `None`
/// (Python's literal `None` result for `?start: [A]` on `""` with
/// `maybe_placeholders`, #289/#382). Mirrors the public API's `ParseTree::None`
/// (ADR-0033) so the bake stays byte-faithful to core.
#[derive(Clone, Debug)]
pub enum ParseTree {
    Tree(Tree),
    Token(Token),
    None,
}

enum NodeValue {
    Token(Token),
    Tree(Tree),
    Inline(Vec<Child>),
}

impl fmt::Display for Tree {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let children: Vec<String> = self
            .children
            .iter()
            .map(|c| match c {
                Child::Tree(t) => t.to_string(),
                Child::Token(tok) => format!("Token({}, {:?})", tok.type_, tok.value),
                Child::None => "None".to_string(),
            })
            .collect();
        write!(f, "Tree({}, [{}])", self.data, children.join(", "))
    }
}

impl fmt::Display for ParseTree {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ParseTree::Tree(t) => write!(f, "{}", t),
            ParseTree::Token(tok) => write!(f, "Token({}, {:?})", tok.type_, tok.value),
            ParseTree::None => write!(f, "None"),
        }
    }
}

// ───────────────────────────── lexer ─────────────────────────────

struct Scanner {
    re: Regex,
    /// (terminal id, capture-group index), in alternation order.
    groups: Vec<(u32, usize)>,
    /// Keyword retype per regex terminal: exact values hashed, `"..."i`
    /// keywords as anchored case-insensitive regexes (definition order).
    unless: HashMap<u32, (HashMap<String, u32>, Vec<(Regex, u32)>)>,
}

impl Scanner {
    fn new(data: &GrammarData) -> Scanner {
        let mut parts: Vec<String> = Vec::with_capacity(data.scan_groups.len());
        for (id, rx) in data.scan_groups {
            parts.push(format!("(?P<g{}>{})", id, rx));
        }
        let pattern = format!("{}{}", data.global_prefix, parts.join("|"));
        let re = Regex::new(&pattern).expect("baked scanner regex is valid");
        // Resolve each group's name to its capture index (a terminal pattern can
        // itself contain groups, so the index is not the alternation position).
        let name_to_idx: HashMap<String, usize> = re
            .capture_names()
            .enumerate()
            .filter_map(|(i, n)| n.map(|n| (n.to_string(), i)))
            .collect();
        let groups = data
            .scan_groups
            .iter()
            .map(|(id, _)| (*id, name_to_idx[&format!("g{}", id)]))
            .collect();
        let mut unless: HashMap<u32, (HashMap<String, u32>, Vec<(Regex, u32)>)> = HashMap::new();
        for (re_id, entries) in data.unless {
            let slot = unless.entry(*re_id).or_default();
            for (value, ci, kw_id) in *entries {
                if *ci {
                    let src = format!("^(?i:{})$", regex::escape(value));
                    let re = Regex::new(&src).expect("baked unless regex is valid");
                    slot.1.push((re, *kw_id));
                } else {
                    slot.0.entry(value.to_string()).or_insert(*kw_id);
                }
            }
        }
        Scanner { re, groups, unless }
    }

    /// Match a single token starting exactly at `pos`. `None` = nothing here.
    fn match_at<'t>(&self, text: &'t str, pos: usize) -> Option<(u32, &'t str)> {
        let caps = self.re.captures_at(text, pos)?;
        let m0 = caps.get(0)?;
        // Accept only a non-empty match beginning exactly at `pos`.
        if m0.start() != pos || m0.end() == pos {
            return None;
        }
        let value = m0.as_str();
        for (id, idx) in &self.groups {
            if caps.get(*idx).is_some() {
                let ty = self
                    .unless
                    .get(id)
                    .and_then(|(exact, ci)| {
                        exact.get(value).copied().or_else(|| {
                            ci.iter()
                                .find(|(re, _)| re.is_match(value))
                                .map(|(_, k)| *k)
                        })
                    })
                    .unwrap_or(*id);
                return Some((ty, value));
            }
        }
        None
    }
}

fn lex(data: &GrammarData, scanner: &Scanner, text: &str) -> Result<Vec<Token>, String> {
    let ignore: HashSet<u32> = data.ignore.iter().copied().collect();
    let mut tokens = Vec::new();
    // `pos` is the **byte** offset (drives regex slicing); `char_pos` is the
    // **character** index a token's `start_pos`/`end_pos` carry — Python parity,
    // the two diverge on non-ASCII input (#278). Both advance together.
    let mut pos = 0usize;
    let mut char_pos = 0usize;
    let mut line = 1usize;
    let mut col = 1usize;

    while pos < text.len() {
        match scanner.match_at(text, pos) {
            Some((id, value)) => {
                let start_line = line;
                let start_col = col;
                let start_pos = char_pos;
                for ch in value.chars() {
                    if ch == '\n' {
                        line += 1;
                        col = 1;
                    } else {
                        col += 1;
                    }
                    char_pos += 1;
                }
                pos += value.len();
                if !ignore.contains(&id) {
                    tokens.push(Token {
                        type_id: id,
                        type_: data.name_of(id),
                        value: value.to_string(),
                        line: start_line,
                        column: start_col,
                        end_line: line,
                        end_column: col,
                        start_pos,
                        end_pos: char_pos,
                    });
                }
            }
            None => {
                let ch = text[pos..].chars().next().unwrap();
                return Err(format!(
                    "Unexpected character {:?} at line {}, column {}",
                    ch, line, col
                ));
            }
        }
    }

    // End-of-input sentinel (terminal id 0 = $END); carries the char index (#278).
    tokens.push(Token {
        type_id: 0,
        type_: data.name_of(0),
        value: String::new(),
        line,
        column: col,
        end_line: line,
        end_column: col,
        start_pos: char_pos,
        end_pos: char_pos,
    });
    Ok(tokens)
}

// ───────────────────────────── parser ─────────────────────────────

fn keep_token(rule: &RuleData, pos: usize) -> bool {
    rule.keep_all || !rule.filter_pos.get(pos).copied().unwrap_or(false)
}

fn nones_at(rule: &RuleData, gap: usize) -> u32 {
    rule.nones_before.get(gap).copied().unwrap_or(0)
}

/// The container span of a rule's **pre-filter** children — the first/last
/// positioned child's start/end, including filtered punctuation tokens the tree
/// drops. The standalone mirror of `tree_builder::ContainerSpan` (Python's
/// `PropagatePositions._pp_get_meta`), the #402 regression net: built by streaming
/// every child value past `observe_*` left-to-right, then applied with `widen_meta`.
#[derive(Default)]
struct ContainerSpan {
    first: Option<Meta>,
    last: Option<Meta>,
}

impl ContainerSpan {
    fn observe(&mut self, meta: Meta) {
        if self.first.is_none() {
            self.first = Some(meta.clone());
        }
        self.last = Some(meta);
    }

    fn observe_token(&mut self, t: &Token) {
        self.observe(Meta {
            line: Some(t.line),
            column: Some(t.column),
            end_line: Some(t.end_line),
            end_column: Some(t.end_column),
            start_pos: Some(t.start_pos),
            end_pos: Some(t.end_pos),
            empty: false,
        });
    }

    fn observe_meta(&mut self, meta: &Meta) {
        if !meta.empty && meta.line.is_some() {
            self.observe(meta.clone());
        }
    }

    fn observe_child(&mut self, c: &Child) {
        match c {
            Child::Token(t) => self.observe_token(t),
            Child::Tree(t) => self.observe_meta(&t.meta),
            Child::None => {}
        }
    }

    /// Widen `meta`'s span to the container: start fields from the first positioned
    /// child, end fields from the last. A node with no positioned pre-filter child
    /// is left untouched (an empty production).
    fn widen_meta(&self, meta: &mut Meta) {
        if let Some(first) = &self.first {
            meta.line = first.line;
            meta.column = first.column;
            meta.start_pos = first.start_pos;
            meta.empty = false;
        }
        if let Some(last) = &self.last {
            meta.end_line = last.end_line;
            meta.end_column = last.end_column;
            meta.end_pos = last.end_pos;
            meta.empty = false;
        }
    }
}

fn shape(
    data: &GrammarData,
    rule: &RuleData,
    mut children: Vec<Child>,
    container: ContainerSpan,
) -> NodeValue {
    for _ in 0..rule.placeholder_count {
        children.push(Child::None);
    }
    for _ in 0..nones_at(rule, rule.len as usize) {
        children.push(Child::None);
    }
    if rule.transparent {
        // `_rule` / `__anon_*`: splice into the parent. No node is built, so there
        // is no `meta` to widen — the spliced children carry their own positions up.
        NodeValue::Inline(children)
    } else if rule.expand1 && !rule.has_alias && children.len() == 1 {
        // `?rule` with a single child: return that child directly. A lone `None`
        // placeholder (`?w: [A]` on the absent branch) collapses exactly like a
        // real single child — Python/core yield `start[None]`, not `start[w[None]]`
        // (bounty RC9; the `?` collapse is purely arity-1, never value-typed). This
        // mirrors `TreeOutputBuilder::shape`'s RC9 carve-out in
        // `parsers/tree_builder.rs` so the baked runtime stays byte-faithful to core.
        //
        // No container widening here: Python's `PropagatePositions` only sets meta
        // when its node builder returns a `Tree`; an expand1 collapse to a bare
        // token/tree keeps that value's own span.
        match children.pop().unwrap() {
            Child::Tree(t) => NodeValue::Tree(t),
            Child::Token(t) => NodeValue::Token(t),
            // A bare `None` has no Token/Tree slot; carry it as a single-None
            // inline so the parent splices exactly one `Child::None` in place.
            Child::None => NodeValue::Inline(vec![Child::None]),
        }
    } else {
        let mut meta = Meta::from_children(&children);
        if data.propagate_positions {
            container.widen_meta(&mut meta);
        }
        NodeValue::Tree(Tree {
            data: rule.tree_name,
            children,
            meta,
        })
    }
}

fn assemble(data: &GrammarData, rule_idx: usize, child_values: Vec<NodeValue>) -> NodeValue {
    let rule = &data.rules[rule_idx];
    let mut children: Vec<Child> = Vec::new();
    // Under `propagate_positions`, the node's span comes from the *pre*-filter
    // children (so a filtered `"("`/`")"` still bounds the span — #402), so observe
    // every value as it streams by, kept or dropped, before the kept list is shaped.
    let mut container = ContainerSpan::default();
    for (i, value) in child_values.into_iter().enumerate() {
        for _ in 0..nones_at(rule, i) {
            children.push(Child::None);
        }
        match value {
            NodeValue::Token(t) => {
                if data.propagate_positions {
                    container.observe_token(&t);
                }
                if keep_token(rule, i) {
                    children.push(Child::Token(t));
                }
            }
            NodeValue::Tree(t) => {
                if data.propagate_positions {
                    container.observe_meta(&t.meta);
                }
                children.push(Child::Tree(t));
            }
            NodeValue::Inline(cs) => {
                if data.propagate_positions {
                    for c in &cs {
                        container.observe_child(c);
                    }
                }
                children.extend(cs);
            }
        }
    }
    shape(data, rule, children, container)
}

fn run(data: &GrammarData, tokens: &[Token], start_state: usize) -> Result<ParseTree, String> {
    let mut state_stack: Vec<usize> = vec![start_state];
    let mut value_stack: Vec<NodeValue> = Vec::new();
    let mut i = 0usize;

    loop {
        let state = *state_stack.last().unwrap();
        let token = &tokens[i];
        match data.action_at(state, token.type_id) {
            Some(Action::Shift(ns)) => {
                i += 1;
                state_stack.push(ns as usize);
                value_stack.push(NodeValue::Token(token.clone()));
            }
            Some(Action::Reduce(r)) => {
                let rule = &data.rules[r as usize];
                let len = rule.len as usize;
                let child_values: Vec<NodeValue> = value_stack.split_off(value_stack.len() - len);
                for _ in 0..len {
                    state_stack.pop();
                }
                let value = assemble(data, r as usize, child_values);
                let top = *state_stack.last().unwrap();
                let nt_index = rule.origin - data.n_terminals;
                let next = data.goto_at(top, nt_index).expect("missing goto entry");
                state_stack.push(next as usize);
                value_stack.push(value);
            }
            Some(Action::Accept) => {
                return match value_stack.pop() {
                    Some(NodeValue::Tree(t)) => Ok(ParseTree::Tree(t)),
                    Some(NodeValue::Token(t)) => Ok(ParseTree::Token(t)),
                    // A top-level `?start` collapsing a lone-`None` placeholder
                    // (`?start: [A]` on `""`) reaches accept as `Inline([None])`
                    // (the RC9 collapse in `shape`). Python Lark and every in-process
                    // backend return a bare `None` here, so emit `ParseTree::None`
                    // to match the oracle (#289/#382, ADR-0033; mirrors `lalr.rs`).
                    Some(NodeValue::Inline(cs))
                        if cs.len() == 1 && matches!(cs[0], Child::None) =>
                    {
                        Ok(ParseTree::None)
                    }
                    _ => Err("accept with empty value stack".to_string()),
                };
            }
            None => {
                let expected: Vec<&str> = data.action[state]
                    .iter()
                    .map(|(t, _)| data.name_of(*t))
                    .collect();
                if token.type_id == 0 {
                    return Err(format!(
                        "Unexpected end of input at line {}, column {}. Expected one of: {:?}",
                        token.line, token.column, expected
                    ));
                }
                return Err(format!(
                    "Unexpected token {:?} ({}) at line {}, column {}. Expected one of: {:?}",
                    token.value, token.type_, token.line, token.column, expected
                ));
            }
        }
    }
}

fn start_state_for(data: &GrammarData, start: Option<&str>) -> Result<usize, String> {
    let name = start.unwrap_or(data.start_default);
    for (n, s) in data.start_states {
        if *n == name {
            return Ok(*s as usize);
        }
    }
    Err(format!("unknown start symbol {:?}", name))
}

// ─────────────────── semantic output seam (issue #234, C9) ───────────────────
//
// The value-parametric mirror of the in-process `OutputBuilder` seam
// (`parsers/tree_builder.rs`, #232 C7): the *same* engine-driven tree shaping
// (per-position punctuation filtering, transparent / `?`-expand1 collapse,
// `maybe_placeholders`, `Discard`), but over an [`OutputBuilder`]'s opaque `Value`
// instead of the runtime's own `Child`/`Tree`. A generated standalone parser can
// therefore drive a semantic backend (`Parser::parse_into`) that never materializes
// the runtime's tree — exactly as `Lark::parse_into` does in-process. The tree path
// (`run`/`assemble`/`shape` above) is untouched, so the committed tree fixtures stay
// byte-for-byte identical.
//
// This is baked verbatim into every generated parser, so it must depend only on
// `regex` + std (no lark-rs items), like the rest of `runtime.rs`. It is a faithful
// re-expression of the crate's `shape_reduction`, kept byte-identical for the tree
// case by the round-trip fixtures and — for the semantic case — by the C1 transformer
// oracle replayed through this seam in `src/standalone/mod.rs`.

/// A cheap borrow of the baked metadata a semantic builder needs to resolve a rule
/// index / terminal id back to the Python-side name world it dispatches on — the
/// standalone mirror of the crate's `OutputContext`. Holds no owned data.
pub struct OutputContext<'g> {
    data: &'g GrammarData,
}

impl<'g> OutputContext<'g> {
    /// The callback name Python's `create_callback` dispatches on for a reduction of
    /// `rule_idx`: the rule's `-> alias`, else its origin/template name — exactly the
    /// `tree_name` the tree path stamps into `Tree::data`, so a builder keyed by
    /// callback name matches Python without re-deriving anything.
    pub fn callback_name(&self, rule_idx: usize) -> &'g str {
        self.data.rules[rule_idx].tree_name
    }

    /// The terminal type name for a shifted token's interned id (the `Token::type_`
    /// world), e.g. `"NUMBER"`.
    pub fn terminal_name(&self, terminal: u32) -> &'g str {
        self.data.name_of(terminal)
    }
}

/// The value-parametric semantic-output seam — the standalone mirror of the crate's
/// [`OutputBuilder`](../../parsers/tree_builder.rs). The engine drives all tree
/// shaping (filtering, transparent/expand1 splicing, placeholder insertion,
/// `Discard`) and calls the builder only with the flat, already-shaped children.
///
/// `'i` ties a borrowing builder's `Value` to the parse `input` (owned backends
/// ignore it). `Parser::parse_into` drives an arbitrary builder; the built-in
/// `parse()` keeps the concrete tree path.
pub trait OutputBuilder<'i> {
    /// The value carried on the parse stack (Yacc's semantic value).
    type Value;

    /// A shifted terminal. Runs for *every* shifted terminal (the parse stack always
    /// needs a value) — engine token materialization, lower-level than Python's
    /// *visible* terminal callback. `ctx` resolves the interned terminal id to its
    /// Python-side name; `input` is the whole source so a span backend can borrow.
    fn token(&mut self, token: Token, input: &'i str, ctx: &OutputContext) -> Self::Value;

    /// A completed reduction of `rule_idx` over its already-shaped `children` (the
    /// engine did all filtering / transparent-splicing / placeholder insertion).
    /// `meta` is the node's engine-computed span. `ctx.callback_name(rule_idx)`
    /// resolves the name Python's `create_callback` dispatches on.
    fn reduce(
        &mut self,
        rule_idx: usize,
        children: &mut Vec<Self::Value>,
        meta: &Meta,
        ctx: &OutputContext,
    ) -> Self::Value;

    /// The value for an absent `maybe_placeholders` optional (`[...]`). Python Lark
    /// inserts a literal `None` child; a builder maps that to its own "absent" value.
    /// Default panics — a builder used with a `maybe_placeholders` grammar MUST
    /// override this.
    fn placeholder(&mut self, _ctx: &OutputContext) -> Self::Value {
        panic!(
            "OutputBuilder::placeholder called: this builder was used with a \
             maybe_placeholders grammar but does not implement placeholder()"
        );
    }

    /// Discard hook (Python's `Discard` sentinel). Default: nothing discards, so the
    /// engine skips the check and non-discarding builders pay zero. The engine drops
    /// discarded children *after* placeholder insertion.
    fn is_discard(&self, _value: &Self::Value) -> bool {
        false
    }
}

/// Origin tag for a generic stack value — the shaping decisions the opaque `Value`
/// cannot answer (which `child_*` meta rule applies, whether an `expand1` lone child
/// is a `None` placeholder). Mirrors the crate's `GTag`.
#[derive(Clone, Copy, PartialEq, Eq)]
enum GTag {
    Token,
    Tree,
    None,
}

/// One value on the generic parse stack: the builder value plus the engine-tracked
/// `meta` and `tag`, kept beside the value so shaping never inspects it.
struct GElem<V> {
    value: V,
    meta: Meta,
    tag: GTag,
}

/// The generic stack currency (the `Value`-parametric analog of [`NodeValue`]): a
/// single value, or the children of a transparent rule to splice into the parent.
enum GSlot<V> {
    Value(GElem<V>),
    Inline(Vec<GElem<V>>),
}

// Tag-aware mirrors of the `child_*` position helpers above, so a generic node's
// `meta` is computed byte-for-byte like `Meta::from_children` over `(Meta, GTag)`
// pairs (Token guards `> 0` on line/column; Tree reads meta directly; None
// contributes nothing).
fn gc_line(m: &Meta, tag: GTag) -> Option<usize> {
    match tag {
        GTag::Token => m.line.filter(|&l| l > 0),
        GTag::Tree => m.line,
        GTag::None => Option::None,
    }
}
fn gc_column(m: &Meta, tag: GTag) -> Option<usize> {
    match tag {
        GTag::Token => m.column.filter(|&c| c > 0),
        GTag::Tree => m.column,
        GTag::None => Option::None,
    }
}
fn gc_start(m: &Meta, tag: GTag) -> Option<usize> {
    match tag {
        GTag::None => Option::None,
        _ => m.start_pos,
    }
}
fn gc_end_line(m: &Meta, tag: GTag) -> Option<usize> {
    match tag {
        GTag::Token => m.end_line.filter(|&l| l > 0),
        GTag::Tree => m.end_line,
        GTag::None => Option::None,
    }
}
fn gc_end_column(m: &Meta, tag: GTag) -> Option<usize> {
    match tag {
        GTag::Token => m.end_column.filter(|&c| c > 0),
        GTag::Tree => m.end_column,
        GTag::None => Option::None,
    }
}
fn gc_end(m: &Meta, tag: GTag) -> Option<usize> {
    match tag {
        GTag::None => Option::None,
        _ => m.end_pos,
    }
}

/// The `Meta` a shifted token contributes (all fields present, unguarded — the raw
/// form `ContainerSpan::observe_token` uses).
fn meta_from_token(t: &Token) -> Meta {
    Meta {
        line: Some(t.line),
        column: Some(t.column),
        end_line: Some(t.end_line),
        end_column: Some(t.end_column),
        start_pos: Some(t.start_pos),
        end_pos: Some(t.end_pos),
        empty: false,
    }
}

/// The `Meta` a node builds from its (post-filter, placeholder-inclusive) children —
/// the `Meta::from_children` contract reproduced over `GElem`s so the engine (not the
/// opaque value) is the single source of a node's span.
fn node_meta_from_elems<V>(elems: &[GElem<V>]) -> Meta {
    let mut meta = Meta::default();
    for e in elems {
        if let Some(line) = gc_line(&e.meta, e.tag) {
            meta.line = Some(line);
            meta.column = gc_column(&e.meta, e.tag);
            meta.start_pos = gc_start(&e.meta, e.tag);
            break;
        }
    }
    for e in elems.iter().rev() {
        if let Some(line) = gc_end_line(&e.meta, e.tag) {
            meta.end_line = Some(line);
            meta.end_column = gc_end_column(&e.meta, e.tag);
            meta.end_pos = gc_end(&e.meta, e.tag);
            break;
        }
    }
    meta.empty = meta.line.is_none();
    meta
}

impl ContainerSpan {
    /// Observe a generic pre-filter child (the `GElem` analog of `observe_child`).
    fn observe_gelem<V>(&mut self, e: &GElem<V>) {
        match e.tag {
            GTag::Token => self.observe(e.meta.clone()),
            GTag::Tree => self.observe_meta(&e.meta),
            GTag::None => {}
        }
    }
}

/// Shape one reduction of `rule` over its child stack slots into the parent value —
/// the value-parametric mirror of `assemble` + `shape`. `builder` mints
/// token/node/placeholder values; the engine owns every shaping decision.
fn shape_reduction<'i, B: OutputBuilder<'i>>(
    data: &GrammarData,
    rule_idx: usize,
    child_slots: Vec<GSlot<B::Value>>,
    builder: &mut B,
    ctx: &OutputContext,
) -> GSlot<B::Value> {
    let rule = &data.rules[rule_idx];

    // Flatten to the kept child list (drop per-position filtered punctuation, splice
    // transparent inlines, insert `nones_before` placeholders), accumulating the
    // pre-filter container span exactly as `assemble` does.
    let mut kept: Vec<GElem<B::Value>> = Vec::new();
    let mut container = ContainerSpan::default();
    for (i, slot) in child_slots.into_iter().enumerate() {
        for _ in 0..nones_at(rule, i) {
            kept.push(GElem {
                value: builder.placeholder(ctx),
                meta: Meta::default(),
                tag: GTag::None,
            });
        }
        match slot {
            GSlot::Value(e) => {
                if data.propagate_positions {
                    container.observe_gelem(&e);
                }
                let filtered = e.tag == GTag::Token && !keep_token(rule, i);
                if !filtered {
                    kept.push(e);
                }
            }
            GSlot::Inline(cs) => {
                if data.propagate_positions {
                    for c in &cs {
                        container.observe_gelem(c);
                    }
                }
                kept.extend(cs);
            }
        }
    }
    // Trailing placeholders: an empty `[...]`'s widest-alternative count, plus a
    // distributed absent `[...]` at the end of this alternative.
    for _ in 0..rule.placeholder_count {
        kept.push(GElem {
            value: builder.placeholder(ctx),
            meta: Meta::default(),
            tag: GTag::None,
        });
    }
    for _ in 0..nones_at(rule, rule.len as usize) {
        kept.push(GElem {
            value: builder.placeholder(ctx),
            meta: Meta::default(),
            tag: GTag::None,
        });
    }

    // `Discard` sweep: after placeholders, before the node is built. Monomorphized
    // away for the default (non-discarding) builder.
    kept.retain(|e| !builder.is_discard(&e.value));

    if rule.transparent {
        // `_rule` / `__anon_*`: splice into the parent, no node built.
        GSlot::Inline(kept)
    } else if rule.expand1 && !rule.has_alias && kept.len() == 1 {
        // `?rule` with a single child: propagate it unchanged. A lone `None`
        // placeholder stays an inline of exactly one `None` (RC9/#289), so the parent
        // splices one placeholder; a real single child collapses to a bare value.
        let e = kept.pop().unwrap();
        match e.tag {
            GTag::None => GSlot::Inline(vec![e]),
            _ => GSlot::Value(e),
        }
    } else {
        let mut node_meta = node_meta_from_elems(&kept);
        if data.propagate_positions {
            container.widen_meta(&mut node_meta);
        }
        let mut values: Vec<B::Value> = kept.into_iter().map(|e| e.value).collect();
        let value = builder.reduce(rule_idx, &mut values, &node_meta, ctx);
        GSlot::Value(GElem {
            value,
            meta: node_meta,
            tag: GTag::Tree,
        })
    }
}

/// The value-parametric parse loop — the `run` analog that drives an
/// [`OutputBuilder`] instead of building the runtime's own tree. Mirrors `run`'s
/// shift/reduce/accept loop exactly, so a semantic backend sees the same shaped
/// reductions in the same order.
fn run_into<'i, B: OutputBuilder<'i>>(
    data: &GrammarData,
    tokens: &[Token],
    start_state: usize,
    input: &'i str,
    builder: &mut B,
) -> Result<B::Value, String> {
    let ctx = OutputContext { data };
    let mut state_stack: Vec<usize> = vec![start_state];
    let mut value_stack: Vec<GSlot<B::Value>> = Vec::new();
    let mut i = 0usize;

    loop {
        let state = *state_stack.last().unwrap();
        let token = &tokens[i];
        match data.action_at(state, token.type_id) {
            Some(Action::Shift(ns)) => {
                i += 1;
                state_stack.push(ns as usize);
                let meta = meta_from_token(token);
                let value = builder.token(token.clone(), input, &ctx);
                value_stack.push(GSlot::Value(GElem {
                    value,
                    meta,
                    tag: GTag::Token,
                }));
            }
            Some(Action::Reduce(r)) => {
                let rule = &data.rules[r as usize];
                let len = rule.len as usize;
                let child_slots: Vec<GSlot<B::Value>> =
                    value_stack.split_off(value_stack.len() - len);
                for _ in 0..len {
                    state_stack.pop();
                }
                let value = shape_reduction(data, r as usize, child_slots, builder, &ctx);
                let top = *state_stack.last().unwrap();
                let nt_index = rule.origin - data.n_terminals;
                let next = data.goto_at(top, nt_index).expect("missing goto entry");
                state_stack.push(next as usize);
                value_stack.push(value);
            }
            Some(Action::Accept) => {
                return match value_stack.pop() {
                    Some(GSlot::Value(e)) => Ok(e.value),
                    // A top-level `?start` lone-`None` placeholder collapse
                    // (`?start: [A]` on `""`) reaches accept as `Inline([None])`; its
                    // single placeholder value is the result (the None-root, #289/#382).
                    Some(GSlot::Inline(mut es)) if es.len() == 1 => Ok(es.pop().unwrap().value),
                    _ => Err("accept with empty value stack".to_string()),
                };
            }
            None => {
                let expected: Vec<&str> = data.action[state]
                    .iter()
                    .map(|(t, _)| data.name_of(*t))
                    .collect();
                if token.type_id == 0 {
                    return Err(format!(
                        "Unexpected end of input at line {}, column {}. Expected one of: {:?}",
                        token.line, token.column, expected
                    ));
                }
                return Err(format!(
                    "Unexpected token {:?} ({}) at line {}, column {}. Expected one of: {:?}",
                    token.value, token.type_, token.line, token.column, expected
                ));
            }
        }
    }
}

/// A self-contained parser over a baked [`GrammarData`].
pub struct Parser {
    data: &'static GrammarData,
    scanner: Scanner,
}

impl Parser {
    /// Build a parser for the given baked grammar (compiles the lexer regex once).
    /// The generated file adds a `Parser::new()` that calls this with its `&DATA`.
    pub fn from_data(data: &'static GrammarData) -> Parser {
        let scanner = Scanner::new(data);
        Parser { data, scanner }
    }

    /// Parse `text` from the default start symbol.
    pub fn parse(&self, text: &str) -> Result<ParseTree, String> {
        self.parse_from(text, None)
    }

    /// Parse `text` from the named start symbol.
    pub fn parse_from(&self, text: &str, start: Option<&str>) -> Result<ParseTree, String> {
        let tokens = lex(self.data, &self.scanner, text)?;
        let start_state = start_state_for(self.data, start)?;
        run(self.data, &tokens, start_state)
    }

    /// Parse `text` directly into an [`OutputBuilder`]'s values, without building the
    /// runtime's own tree (issue #234, C9). The engine drives the builder during the
    /// parse — a shifted terminal calls [`token`](OutputBuilder::token), a completed
    /// reduction calls [`reduce`](OutputBuilder::reduce) over its already-shaped
    /// children — the standalone mirror of `Lark::parse_into`. `parse()` is exactly
    /// this with the built-in tree backend.
    pub fn parse_into<'i, B: OutputBuilder<'i>>(
        &self,
        text: &'i str,
        builder: &mut B,
    ) -> Result<B::Value, String> {
        self.parse_into_from(text, None, builder)
    }

    /// [`parse_into`](Self::parse_into) from an explicit start symbol.
    pub fn parse_into_from<'i, B: OutputBuilder<'i>>(
        &self,
        text: &'i str,
        start: Option<&str>,
        builder: &mut B,
    ) -> Result<B::Value, String> {
        let tokens = lex(self.data, &self.scanner, text)?;
        let start_state = start_state_for(self.data, start)?;
        run_into(self.data, &tokens, start_state, text, builder)
    }
}


